38	// 登记与撤销：各状态工单均可登记；同路径独立登记不合并；撤销保留记录、路径、
39	// 说明与理由；未知编号、重复撤销拒绝；已撤销不能恢复，可重新登记为新索引；
40	// 重载后状态与编号延续保持。
41	func TestAttachRegisterAndRevoke(t *testing.T) {
42		s, dir := newAttachStore(t)
43		file1 := writeAttachFile(t, dir, "photo.jpg")
44	
45		// 未关闭工单登记。
46		a1, err := s.attach("T0001", file1, "卡纸位置照片")
47		if err != nil || a1.ID != "A0001" {
48			t.Fatalf("首次登记: %v %+v", err, a1)
49		}
50		// 同路径再次登记：独立编号，不合并。
51		a2, err := s.attach("T0001", file1, "另一角度照片")
52		if err != nil || a2.ID != "A0002" {
53			t.Fatalf("同路径应独立登记: %v %+v", err, a2)
54		}
55		// 未知工单拒绝，不消耗编号。
56		if _, err := s.attach("T9999", file1, "x"); !errors.Is(err, errNotFound) {
57			t.Fatalf("未知工单应拒绝，得到 %v", err)
58		}
59		// 空说明拒绝。
60		if _, err := s.attach("T0001", file1, ""); !errors.Is(err, errConflict) {
61			t.Fatalf("空说明应拒绝，得到 %v", err)
62		}
63		mustSave(t, s)
64	
65		// 关闭工单后仍可补充资料。
66		if _, _, err := s.closeTicket("T0001", "已修复"); err != nil {
67			t.Fatal(err)
68		}
69		a3, err := s.attach("T0001", file1, "维修后照片")
70		if err != nil || a3.ID != "A0003" {
71			t.Fatalf("已关闭工单登记: %v %+v", err, a3)
72		}
73		// 取消的工单同样可补充资料。
74		if _, _, err := s.report("EQ-1", "无法开机", "req-2"); err != nil { // T0002
75			t.Fatal(err)
76		}
77		if _, _, err := s.cancelTicket("T0002", "误报"); err != nil {
78			t.Fatal(err)
79		}
80		a4, err := s.attach("T0002", file1, "误报说明截图")
81		if err != nil || a4.ID != "A0004" {
82			t.Fatalf("已取消工单登记: %v %+v", err, a4)
83		}
84		mustSave(t, s)
85	
86		// 撤销：保留记录、路径、说明与理由。
87		rev, err := s.revokeAttachment("A0001", "照片拍错设备")
88		if err != nil {
89			t.Fatalf("撤销: %v", err)
90		}
91		if !rev.Revoked || rev.RevokeReason != "照片拍错设备" ||
92			rev.Path != file1 || rev.Note != "卡纸位置照片" {
93			t.Fatalf("撤销后应保留记录、路径、说明与理由，得到 %+v", rev)
94		}
95		// 未知编号、重复撤销拒绝。
96		if _, err := s.revokeAttachment("A9999", "x"); !errors.Is(err, errNotFound) {
97			t.Fatalf("未知附件编号应拒绝，得到 %v", err)
98		}
99		if _, err := s.revokeAttachment("A0001", "再次"); !errors.Is(err, errConflict) {
100			t.Fatalf("重复撤销应拒绝，得到 %v", err)
101		}
102		// 空理由拒绝。
103		if _, err := s.revokeAttachment("A0002", ""); !errors.Is(err, errConflict) {
104			t.Fatalf("空理由应拒绝，得到 %v", err)
105		}
106		// 撤销不影响同路径其他索引。
107		if a2.Revoked || a3.Revoked {
108			t.Fatal("撤销不应影响同路径其他索引")
109		}
110		// 工单终结不自动撤销附件。
111		if a4.Revoked {
112			t.Fatal("工单取消不应自动撤销附件")
113		}
114		mustSave(t, s)
115	
116		// 重载后索引状态与编号延续保持；已撤销编号不能恢复，可重新登记为新索引。
117		s2, err := openStore(dir)
118		if err != nil {
119			t.Fatalf("重载: %v", err)
120		}
121		if s2.data.NextAttachSeq != 5 {
122			t.Fatalf("下一附件序号 = %d, 想得到 5", s2.data.NextAttachSeq)
123		}
124		got := s2.findAttachment("A0001")
125		if got == nil || !got.Revoked || got.RevokeReason != "照片拍错设备" || got.Note != "卡纸位置照片" {
126			t.Fatalf("重载后撤销状态应保持，得到 %+v", got)
127		}
128		if _, err := s2.revokeAttachment("A0001", "恢复"); !errors.Is(err, errConflict) {
129			t.Fatalf("已撤销编号不能恢复，得到 %v", err)
130		}
131		a5, err := s2.attach("T0001", file1, "重新登记同一文件")
132		if err != nil || a5.ID != "A0005" {
133			t.Fatalf("重新登记应为新索引 A0005: %v %+v", err, a5)
134		}
