138	// 路径解析与文件检查：相对路径按调用时工作目录解析并保存绝对路径；
139	// 不存在、目录形式的路径拒绝，且不消耗附件编号。
140	func TestAttachPathResolutionAndFileChecks(t *testing.T) {
141		s, dir := newAttachStore(t)
142		work := t.TempDir()
143		writeAttachFile(t, work, "photo.jpg")
144		t.Chdir(work)
145	
146		// 相对路径按调用时工作目录解析，保存绝对路径（经命令入口）。
147		var out, errOut bytes.Buffer
148		code := run([]string{"attach", "--ticket-id", "T0001", "--path", "photo.jpg",
149			"--note", "现场照片", "--data-dir", dir}, &out, &errOut)
150		if code != 0 {
151			t.Fatalf("相对路径登记应成功，得到 %d: %s", code, errOut.String())
152		}
153		want := filepath.Join(work, "photo.jpg")
154		a := s.findAttachment("A0001")
155		if a == nil {
156			s2, err := openStore(dir)
157			if err != nil {
158				t.Fatalf("重载: %v", err)
159			}
160			a = s2.findAttachment("A0001")
161		}
162		if a == nil || a.Path != want || !filepath.IsAbs(a.Path) {
163			t.Fatalf("应保存绝对路径 %q，得到 %+v", want, a)
164		}
165	
166		// 不存在的文件拒绝。
167		if _, err := s.attach("T0001", filepath.Join(work, "missing.jpg"), "x"); err == nil {
168			t.Fatal("不存在的文件应拒绝登记")
169		}
170		// 目录不是普通文件，拒绝。
171		if _, err := s.attach("T0001", work, "x"); err == nil {
172			t.Fatal("目录应拒绝登记")
173		}
174		// 命令入口同样拒绝，且不消耗编号。
175		out.Reset()
176		errOut.Reset()
177		code = run([]string{"attach", "--ticket-id", "T0001", "--path", work,
178			"--note", "x", "--data-dir", dir}, &out, &errOut)
179		if code != 1 {
180			t.Fatalf("目录登记应退出 1，得到 %d", code)
181		}
182		s2, err := openStore(dir)
183		if err != nil {
184			t.Fatalf("重载: %v", err)
185		}
186		if s2.data.NextAttachSeq != 2 || len(s2.data.Attachments) != 1 {
187			t.Fatal("失败的登记不应消耗编号或留下记录")
188		}
189		if got := s2.findAttachment("A0001"); got == nil || got.Path != want {
190			t.Fatalf("重载后路径应保持，得到 %+v", got)
191		}
192	}
193	
194	// 文件失联：登记后文件消失或成为目录仅使引用不可用，不阻止撤销及其他业务，
195	// 也不影响整库一致性校验。
196	func TestAttachFileLaterUnavailable(t *testing.T) {
197		s, dir := newAttachStore(t)
198		gone := writeAttachFile(t, dir, "gone.jpg")
199		becomeDir := writeAttachFile(t, dir, "become-dir.jpg")
200		if _, err := s.attach("T0001", gone, "会消失的文件"); err != nil { // A0001
201			t.Fatal(err)
202		}
203		if _, err := s.attach("T0001", becomeDir, "会变成目录的文件"); err != nil { // A0002
204			t.Fatal(err)
205		}
206		mustSave(t, s)
207	
208		// 文件日后消失、成为目录。
209		if err := os.Remove(gone); err != nil {
210			t.Fatal(err)
211		}
212		if err := os.Remove(becomeDir); err != nil {
213			t.Fatal(err)
214		}
215		if err := os.Mkdir(becomeDir, 0o755); err != nil {
216			t.Fatal(err)
217		}
218		if attachmentReadable(gone) || attachmentReadable(becomeDir) {
219			t.Fatal("消失或成为目录的文件应不可用")
220		}
221	
222		// 整库一致性校验不受文件可用性影响：重载正常。
223		s2, err := openStore(dir)
224		if err != nil {
225			t.Fatalf("文件不可用不应影响加载: %v", err)
226		}
227		// 其他业务不受影响：关闭工单、新报修、新登记（指向存在的文件）。
228		if _, _, err := s2.closeTicket("T0001", "已修复"); err != nil {
229			t.Fatalf("文件不可用不应阻止关闭工单: %v", err)
230		}
231		ok := writeAttachFile(t, dir, "ok.jpg")
232		if _, err := s2.attach("T0001", ok, "新资料"); err != nil { // A0003
233			t.Fatalf("文件不可用不应阻止新登记: %v", err)
234		}
235		// 撤销不受文件可用性影响。
236		if _, err := s2.revokeAttachment("A0001", "文件已丢失"); err != nil {
237			t.Fatalf("文件不可用不应阻止撤销: %v", err)
238		}
239		mustSave(t, s2)
240	
241		// 重载后状态保持。
242		s3, err := openStore(dir)
243		if err != nil {
244			t.Fatalf("重载: %v", err)
245		}
246		if a := s3.findAttachment("A0001"); a == nil || !a.Revoked || a.RevokeReason != "文件已丢失" {
247			t.Fatalf("撤销状态应保持，得到 %+v", a)
248		}
249		if a := s3.findAttachment("A0002"); a == nil || a.Revoked {
250			t.Fatalf("A0002 应仍为有效，得到 %+v", a)
251		}
252	}
253	
254	// 无附件字段的有效旧库直接使用：缺省视为没有附件索引，附件编号从 A0001 开始。
255	func TestLegacyStoreWithoutAttachments(t *testing.T) {
256		dir := t.TempDir()
257		writeLedger(t, dir, nil) // 旧格式台账，无 attachments 与 next_attach_seq 字段
258		s, err := openStore(dir)
259		if err != nil {
260			t.Fatalf("无附件字段的旧库应能加载: %v", err)
261		}
262		file := writeAttachFile(t, dir, "photo.jpg")
263		a, err := s.attach("T0001", file, "现场照片")
264		if err != nil || a.ID != "A0001" {
265			t.Fatalf("旧库首条附件编号应为 A0001: %v %+v", err, a)
266		}
267		mustSave(t, s)
268		s2, err := openStore(dir)
269		if err != nil {
270			t.Fatalf("登记后重载: %v", err)
271		}
272		if got := s2.findAttachment("A0001"); got == nil || got.Path != file || got.Note != "现场照片" {
273			t.Fatalf("重载后附件记录应保持，得到 %+v", got)
274		}
275	}
276	
277	// 导入接续：有效与已撤销索引及履历随资产复制，附件编号按源登记履历序号整体
278	// 重分配并输出映射，工单及履历引用同步替换；路径、状态、说明、理由保持；
279	// 不复制文件，文件不可用不使导入失败；源只读，目标原有记录不变，导入后可继续登记。
280	func TestImportAttachmentsRemapAndContinue(t *testing.T) {
281		srcDir := filepath.Join(t.TempDir(), "src")
282		dstDir := filepath.Join(t.TempDir(), "dst")
283		files := t.TempDir()
284	
285		// 源：EQ-A 一张已关闭工单（有效附件 A0001、已撤销附件 A0002）与一张未关闭
286		// 工单（附件 A0003，登记后文件删除——文件不可用不使导入失败）。
287		src := newStoreAt(t, srcDir)
288		if _, err := src.registerAsset("EQ-A", "打印机", "一楼"); err != nil {
289			t.Fatal(err)
290		}
291		if _, _, err := src.report("EQ-A", "卡纸", "req-a1"); err != nil { // T0001
292			t.Fatal(err)
293		}
294		f1 := writeAttachFile(t, files, "p1.jpg")
295		f2 := writeAttachFile(t, files, "p2.jpg")
296		f3 := writeAttachFile(t, files, "p3.jpg")
297		if _, err := src.attach("T0001", f1, "卡纸照片"); err != nil { // A0001
298			t.Fatal(err)
299		}
300		if _, err := src.attach("T0001", f2, "拍错的照片"); err != nil { // A0002
301			t.Fatal(err)
302		}
303		if _, err := src.revokeAttachment("A0002", "拍错设备"); err != nil {
304			t.Fatal(err)
305		}
306		if _, _, err := src.closeTicket("T0001", "已修复"); err != nil {
307			t.Fatal(err)
308		}
309		if _, _, err := src.report("EQ-A", "无法开机", "req-a2"); err != nil { // T0002
310			t.Fatal(err)
311		}
312		if _, err := src.attach("T0002", f3, "电源照片"); err != nil { // A0003
313			t.Fatal(err)
314		}
315		mustSave(t, src)
316		// 登记后文件消失：只使引用不可用，不影响导入。
317		if err := os.Remove(f3); err != nil {
318			t.Fatal(err)
319		}
320		if _, err := openStore(srcDir); err != nil {
321			t.Fatalf("文件不可用不应影响源台账加载: %v", err)
322		}
323	
324		// 目标：EQ-X 一张未关闭工单，已有一条附件 A0001。
325		dst := newStoreAt(t, dstDir)
326		if _, err := dst.registerAsset("EQ-X", "叉车", "仓库"); err != nil {
327			t.Fatal(err)
328		}
329		if _, _, err := dst.report("EQ-X", "抖动", "req-x1"); err != nil { // T0001
330			t.Fatal(err)
331		}
332		fx := writeAttachFile(t, files, "px.jpg")
333		if _, err := dst.attach("T0001", fx, "抖动视频"); err != nil { // A0001
334			t.Fatal(err)
335		}
336		mustSave(t, dst)
337	
338		srcBefore := readFileBytes(t, srcDir)
339		dstBefore := readFileBytes(t, dstDir)
340	
341		outcome, err := importAssets(dstDir, srcDir, []string{"EQ-A"})
342		if err != nil {
343			t.Fatalf("导入失败: %v", err)
344		}
345		wantAttach := []attachRemap{{"A0001", "A0002"}, {"A0002", "A0003"}, {"A0003", "A0004"}}
346		if len(outcome.attachments) != len(wantAttach) {
347			t.Fatalf("附件映射数 = %d, 想得到 %d", len(outcome.attachments), len(wantAttach))
348		}
349		for i, m := range outcome.attachments {
350			if m != wantAttach[i] {
351				t.Fatalf("附件映射[%d] = %v, 想得到 %v", i, m, wantAttach[i])
352			}
353		}
354		if string(readFileBytes(t, srcDir)) != string(srcBefore) {
355			t.Fatal("导入不应修改源台账")
356		}
357		if string(dstBefore) == string(readFileBytes(t, dstDir)) {
358			t.Fatal("目标台账应已更新")
359		}
360	
361		s, err := openStore(dstDir)
362		if err != nil {
363			t.Fatalf("重载目标: %v", err)
364		}
365		if s.data.NextAttachSeq != 5 {
366			t.Fatalf("下一附件序号 = %d, 想得到 5", s.data.NextAttachSeq)
367		}
368		// 目标原有记录不变。
369		orig := s.findAttachment("A0001")
370		if orig == nil || orig.TicketID != "T0001" || orig.Path != fx || orig.Note != "抖动视频" || orig.Revoked {
371			t.Fatalf("目标原有附件 A0001 不应改变，得到 %+v", orig)
372		}
373		// 导入记录：工单引用同步替换，路径、状态、说明、理由保持。
374		a2 := s.findAttachment("A0002")
375		if a2 == nil || a2.TicketID != "T0002" || a2.AssetID != "EQ-A" ||
376			a2.Path != f1 || a2.Note != "卡纸照片" || a2.Revoked {
377			t.Fatalf("导入的 A0002 业务信息应保留，得到 %+v", a2)
378		}
379		a3 := s.findAttachment("A0003")
380		if a3 == nil || !a3.Revoked || a3.RevokeReason != "拍错设备" || a3.Path != f2 {
381			t.Fatalf("导入的已撤销附件状态与理由应保持，得到 %+v", a3)
382		}
383		// 撤销履历的附件引用同步更新。
384		var revEv *Event
385		for i := range s.data.Events {
386			if s.data.Events[i].Kind == eventAttachRevoke {
387				revEv = &s.data.Events[i]
388			}
389		}
390		if revEv == nil || revEv.AttachmentID != "A0003" || revEv.TicketID != "T0002" ||
391			revEv.Path != f2 || revEv.Content != "拍错设备" {
392			t.Fatalf("撤销履历引用应同步更新，得到 %+v", revEv)
393		}
394		// 文件不可用的索引照常导入。
395		a4 := s.findAttachment("A0004")
396		if a4 == nil || a4.TicketID != "T0003" || a4.Path != f3 || a4.Revoked {
397			t.Fatalf("文件不可用的索引应照常导入，得到 %+v", a4)
398		}
399		// 导入后可继续登记，编号延续。
400		f5 := writeAttachFile(t, files, "p5.jpg")
401		a5, err := s.attach("T0003", f5, "补充资料")
402		if err != nil || a5.ID != "A0005" {
403			t.Fatalf("导入后登记应延续编号 A0005: %v %+v", err, a5)
404		}
405		mustSave(t, s)
406		if _, err := openStore(dstDir); err != nil {
407			t.Fatalf("登记后的台账应保持一致: %v", err)
408		}
409	}
410	
411	// 矛盾：附件编号重复、计数器回退、相对路径、缺少或重复登记履历、撤销在登记
412	// 之前、重复撤销、记录内容与履历不一致、撤销状态与履历不符等，加载即拒绝并
413	// 保留原文件字节，不自动修复。
414	func TestAttachmentContradictoryLedgerRejected(t *testing.T) {
415		// 合法基准：T0001 未关闭，A0001 已撤销（登记 + 撤销履历齐全）。
416		base := `{
417	  "version": 1,
418	  "assets": [{"id":"EQ-1","name":"打印机","location":"一楼","status":"维修中"}],
419	  "tickets": [{"id":"T0001","asset_id":"EQ-1","description":"卡纸","request_id":"req-1","status":"未关闭","created_at":"2026-10-01T08:00:00Z"}],
420	  "events": [
421	    {"seq":1,"asset_id":"EQ-1","ticket_id":"T0001","kind":"报修","content":"卡纸","time":"2026-10-01T08:00:00Z"},
422	    {"seq":2,"asset_id":"EQ-1","ticket_id":"T0001","kind":"附件登记","content":"现场照片","attachment_id":"A0001","path":"/tmp/photo.jpg","time":"2026-10-01T09:00:00Z"},
423	    {"seq":3,"asset_id":"EQ-1","ticket_id":"T0001","kind":"附件撤销","content":"拍错了","attachment_id":"A0001","path":"/tmp/photo.jpg","time":"2026-10-01T10:00:00Z"}
424	  ],
425	  "requests": [{"request_id":"req-1","asset_id":"EQ-1","description":"卡纸","ticket_id":"T0001"}],
426	  "attachments": [{"id":"A0001","ticket_id":"T0001","asset_id":"EQ-1","path":"/tmp/photo.jpg","note":"现场照片","revoked":true,"revoke_reason":"拍错了"}],
427	  "next_ticket_seq": 2,
428	  "next_attach_seq": 2
429	}`
430		write := func(t *testing.T, mutate func(m map[string]any)) (string, []byte) {
431			t.Helper()
432			var m map[string]any
433			if err := json.Unmarshal([]byte(base), &m); err != nil {
434				t.Fatal(err)
435			}
436			mutate(m)
437			raw, err := json.Marshal(m)
438			if err != nil {
439				t.Fatal(err)
440			}
441			dir := t.TempDir()
442			if err := os.WriteFile(filepath.Join(dir, dataFileName), raw, 0o644); err != nil {
443				t.Fatal(err)
444			}
445			return dir, raw
446		}
447		eventsOf := func(m map[string]any) []any { return m["events"].([]any) }
448		attachOf := func(m map[string]any) map[string]any { return m["attachments"].([]any)[0].(map[string]any) }
449	
450		cases := []struct {
451			name   string
452			mutate func(m map[string]any)
453		}{
454			{"附件编号重复", func(m map[string]any) {
455				m["attachments"] = append(m["attachments"].([]any), map[string]any{
456					"id": "A0001", "ticket_id": "T0001", "asset_id": "EQ-1",
457					"path": "/tmp/other.jpg", "note": "另一张", "revoked": false,
458				})
459			}},
460			{"下一附件序号不大于已用序号", func(m map[string]any) {
461				m["next_attach_seq"] = 1
462			}},
463			{"附件路径不是绝对路径", func(m map[string]any) {
464				attachOf(m)["path"] = "tmp/photo.jpg"
465			}},
466			{"附件记录引用不存在的工单", func(m map[string]any) {
467				attachOf(m)["ticket_id"] = "T9999"
468			}},
469			{"附件记录缺少登记履历", func(m map[string]any) {
470				m["events"] = eventsOf(m)[:1]
471				attachOf(m)["revoked"] = false
472				delete(attachOf(m), "revoke_reason")
473			}},
474			{"附件记录有多条登记履历", func(m map[string]any) {
475				dup := map[string]any{
476					"seq": 4, "asset_id": "EQ-1", "ticket_id": "T0001", "kind": "附件登记",
477					"content": "现场照片", "attachment_id": "A0001", "path": "/tmp/photo.jpg",
478					"time": "2026-10-01T11:00:00Z",
479				}
480				m["events"] = append(eventsOf(m), dup)
481			}},
482			{"撤销履历在登记履历之前", func(m map[string]any) {
483				eventsOf(m)[1].(map[string]any)["seq"] = 3
484				eventsOf(m)[2].(map[string]any)["seq"] = 2
485			}},
486			{"附件记录有多条撤销履历", func(m map[string]any) {
487				dup := map[string]any{
488					"seq": 4, "asset_id": "EQ-1", "ticket_id": "T0001", "kind": "附件撤销",
489					"content": "拍错了", "attachment_id": "A0001", "path": "/tmp/photo.jpg",
490					"time": "2026-10-01T11:00:00Z",
491				}
492				m["events"] = append(eventsOf(m), dup)
493			}},
494			{"登记履历与记录说明不一致", func(m map[string]any) {
495				eventsOf(m)[1].(map[string]any)["content"] = "另一段说明"
496			}},
497			{"撤销履历与记录理由不一致", func(m map[string]any) {
498				eventsOf(m)[2].(map[string]any)["content"] = "另一个理由"
499			}},
500			{"撤销状态与履历不符", func(m map[string]any) {
501				attachOf(m)["revoked"] = false
502				delete(attachOf(m), "revoke_reason")
503			}},
504			{"登记履历在报修之前", func(m map[string]any) {
505				eventsOf(m)[0].(map[string]any)["seq"] = 5
506			}},
507		}
508		for _, tc := range cases {
509			t.Run(tc.name, func(t *testing.T) {
510				dir, raw := write(t, tc.mutate)
511				if _, err := openStore(dir); err == nil {
512					t.Fatal("矛盾台账应拒绝加载")
513				}
514				if got := readFileBytes(t, dir); string(got) != string(raw) {
515					t.Fatal("拒绝加载不应改动原文件字节")
516				}
517			})
518		}
519	
520		// 基准台账本身合法，可正常加载（路径指向的文件是否存在不参与校验）。
521		dir, _ := write(t, func(m map[string]any) {})
522		s, err := openStore(dir)
523		if err != nil {
524			t.Fatalf("合法台账应能加载: %v", err)
525		}
526		if a := s.findAttachment("A0001"); a == nil || !a.Revoked || a.RevokeReason != "拍错了" {
527			t.Fatalf("合法台账的附件记录应加载，得到 %+v", a)
528		}
529	}
