531	// 失败重载：写入失败保留原文件字节、不留下部分记录、不消耗编号，恢复后可重试。
532	func TestAttachSaveFailureLeavesFileUntouched(t *testing.T) {
533		s, dir := newAttachStore(t)
534		file := writeAttachFile(t, dir, "photo.jpg")
535		if _, err := s.attach("T0001", file, "现场照片"); err != nil {
536			t.Fatal(err)
