566		if len(s3.data.Attachments) != 1 || s3.data.NextAttachSeq != 2 {
567			t.Fatal("写入失败不应留下部分记录，也不应消耗附件编号")
568		}
569		a, err := s3.attach("T0001", file, "另一张")
570		if err != nil || a.ID != "A0002" {
571			t.Fatalf("恢复后重试应分配 A0002: %v %+v", err, a)
572		}
