576	// 命令行入口：参数错误退出 2，业务失败退出 1；ticket 按登记顺序显示附件及
577	// 文件可用性，history 展示登记、撤销履历。
578	func TestAttachCommandLine(t *testing.T) {
579		dir := t.TempDir()
580		files := t.TempDir()
581		photo := writeAttachFile(t, files, "photo.jpg")
582		var out, errOut bytes.Buffer
583		runCmd := func(args ...string) (int, string, string) {
584			out.Reset()
585			errOut.Reset()
586			code := run(append(args, "--data-dir", dir), &out, &errOut)
587			return code, out.String(), errOut.String()
588		}
589	
590		runCmd("register", "--asset-id", "EQ-1", "--name", "打印机", "--location", "一楼")
591		runCmd("report", "--asset-id", "EQ-1", "--description", "卡纸", "--request-id", "req-1")
592	
593		// 参数错误：缺说明、缺路径，退出 2。
594		if code, _, _ := runCmd("attach", "--ticket-id", "T0001", "--path", photo); code != 2 {
595			t.Fatalf("缺少 --note 应退出 2，得到 %d", code)
596		}
597		if code, _, _ := runCmd("attach", "--ticket-id", "T0001", "--note", "x"); code != 2 {
598			t.Fatalf("缺少 --path 应退出 2，得到 %d", code)
599		}
600		if code, _, _ := runCmd("revoke", "--attachment-id", "A0001"); code != 2 {
601			t.Fatalf("缺少 --reason 应退出 2，得到 %d", code)
602		}
603		// 业务失败：未知工单、不存在的文件、未知附件编号，退出 1。
604		if code, _, _ := runCmd("attach", "--ticket-id", "T9999", "--path", photo, "--note", "x"); code != 1 {
605			t.Fatalf("未知工单登记应退出 1，得到 %d", code)
606		}
607		if code, _, _ := runCmd("attach", "--ticket-id", "T0001", "--path", filepath.Join(files, "missing.jpg"), "--note", "x"); code != 1 {
608			t.Fatalf("不存在的文件应退出 1，得到 %d", code)
609		}
610		if code, _, _ := runCmd("revoke", "--attachment-id", "A9999", "--reason", "x"); code != 1 {
611			t.Fatalf("未知附件编号应退出 1，得到 %d", code)
612		}
613	
614		// 成功登记并输出附件编号。
615		code, o, _ := runCmd("attach", "--ticket-id", "T0001", "--path", photo, "--note", "卡纸照片")
616		if code != 0 || !strings.Contains(o, "附件编号: A0001") {
617			t.Fatalf("登记应成功并输出 A0001，得到 %d:\n%s", code, o)
618		}
619		// ticket：有效附件显示文件可读。
620		code, o, _ = runCmd("ticket", "--ticket-id", "T0001")
621		if code != 0 || !strings.Contains(o, "A0001\t"+photo+"\t卡纸照片\t有效（文件可读）") {
622			t.Fatalf("ticket 应显示有效附件及文件可读，得到 %d:\n%s", code, o)
623		}
624		// 撤销成功显示已撤销；重复撤销退出 1。
625		code, o, _ = runCmd("revoke", "--attachment-id", "A0001", "--reason", "拍错设备")
626		if code != 0 || !strings.Contains(o, "附件 A0001 已撤销。") {
627			t.Fatalf("撤销应成功并显示已撤销，得到 %d:\n%s", code, o)
628		}
629		if code, _, _ := runCmd("revoke", "--attachment-id", "A0001", "--reason", "再次"); code != 1 {
630			t.Fatalf("重复撤销应退出 1，得到 %d", code)
631		}
632		// ticket：已撤销状态保留显示。
633		code, o, _ = runCmd("ticket", "--ticket-id", "T0001")
634		if code != 0 || !strings.Contains(o, "A0001\t"+photo+"\t卡纸照片\t已撤销") {
635			t.Fatalf("ticket 应显示已撤销附件，得到 %d:\n%s", code, o)
636		}
637		// 文件消失后有效附件显示不可用。
638		gone := writeAttachFile(t, files, "gone.jpg")
639		runCmd("attach", "--ticket-id", "T0001", "--path", gone, "--note", "会消失")
640		if err := os.Remove(gone); err != nil {
641			t.Fatal(err)
642		}
643		code, o, _ = runCmd("ticket", "--ticket-id", "T0001")
644		if code != 0 || !strings.Contains(o, "A0002\t"+gone+"\t会消失\t有效（文件不可用）") {
645			t.Fatalf("ticket 应显示文件不可用，得到 %d:\n%s", code, o)
646		}
647		// history：展示登记与撤销履历。
648		code, o, _ = runCmd("history", "--asset-id", "EQ-1")
649		if code != 0 ||
650			!strings.Contains(o, "附件登记 工单 T0001: 附件编号 A0001，路径 "+photo+"（卡纸照片）") ||
651			!strings.Contains(o, "附件撤销 工单 T0001: 附件编号 A0001，路径 "+photo+"（拍错设备）") {
652			t.Fatalf("history 应展示附件登记与撤销履历，得到 %d:\n%s", code, o)
653		}
654		// 无记录明确提示。
655		runCmd("register", "--asset-id", "EQ-2", "--name", "空调", "--location", "二楼")
656		runCmd("report", "--asset-id", "EQ-2", "--description", "不制冷", "--request-id", "req-2")
657		code, o, _ = runCmd("ticket", "--ticket-id", "T0002")
658		if code != 0 || !strings.Contains(o, "附件: 无") {
659			t.Fatalf("无附件记录应明确提示，得到 %d:\n%s", code, o)
660		}
661	}
