387	// verifyPackage 完整核对迁移包：包格式与版本、成员集合（无缺失、额外、重复
388	// 成员）、成员类型（仅普通文件，拒绝目录与链接）、成员名（拒绝越界路径）、
389	// 台账格式与业务关联、资料映射、实际成员与内容校验值。任何问题都返回说明
390	// 原因的错误。核对全程只读包文件，不写出任何内容。
391	//
392	// 返回台账数据、附件索引到资料成员名的映射与成员内容（键为成员名）。
393	func verifyPackage(zr *zip.Reader) (*storeData, map[string]string, map[string][]byte, error) {
394		// 成员清单核对：名称唯一、仅普通文件、成员名不越界。
395		members := map[string]*zip.File{}
396		for _, f := range zr.File {
397			name := filepath.ToSlash(f.Name)
398			if name == "" || strings.HasPrefix(name, "/") || strings.HasPrefix(name, "../") ||
399				name == ".." || strings.Contains(name, "/../") || strings.HasSuffix(name, "/..") ||
400				strings.Contains(name, "\\") {
401				return nil, nil, nil, fmt.Errorf("迁移包含有越界成员路径 %q，整包拒绝", f.Name)
402			}
403			if !f.Mode().IsRegular() {
404				return nil, nil, nil, fmt.Errorf("迁移包成员 %s 不是普通文件（拒绝目录或链接成员）", name)
405			}
406			if members[name] != nil {
407				return nil, nil, nil, fmt.Errorf("迁移包成员 %s 重复，整包拒绝", name)
408			}
409			members[name] = f
410		}
411	
412		manifestFile := members[migrateManifestName]
413		if manifestFile == nil {
414			return nil, nil, nil, fmt.Errorf("迁移包缺少清单成员 %s", migrateManifestName)
415		}
416		manifestRaw, err := readZipMember(manifestFile)
417		if err != nil {
418			return nil, nil, nil, fmt.Errorf("读取清单失败: %w", err)
419		}
420		var manifest migrateManifest
421		dec := json.NewDecoder(bytes.NewReader(manifestRaw))
422		dec.DisallowUnknownFields()
423		if err := dec.Decode(&manifest); err != nil {
424			return nil, nil, nil, fmt.Errorf("清单格式无效: %w", err)
425		}
426		if manifest.Format != migrateMagic+"/1" {
427			return nil, nil, nil, fmt.Errorf("未知迁移包格式 %q（本工具支持 %s/1）", manifest.Format, migrateMagic)
428		}
429		if manifest.Version != migrateVersion {
430			return nil, nil, nil, fmt.Errorf("未知迁移包版本 %d：本工具仅支持版本 %d，整包拒绝", manifest.Version, migrateVersion)
431		}
432	
433		// 清单内资料映射自洽：附件编号与成员名均唯一，成员名合法。
434		wantFiles := map[string]bool{}
435		wantAttach := map[string]bool{}
436		for _, fm := range manifest.Files {
437			if fm.AttachmentID == "" || fm.Member == "" || fm.SHA256 == "" {
438				return nil, nil, nil, fmt.Errorf("清单中存在字段不完整的资料条目")
439			}
440			if wantAttach[fm.AttachmentID] {
441				return nil, nil, nil, fmt.Errorf("清单中附件编号 %s 的资料条目重复", fm.AttachmentID)
442			}
443			wantAttach[fm.AttachmentID] = true
444			if wantFiles[fm.Member] {
445				return nil, nil, nil, fmt.Errorf("清单中资料成员 %s 重复", fm.Member)
446			}
447			if !fileMemberPattern.MatchString(fm.Member) {
448				return nil, nil, nil, fmt.Errorf("清单中资料成员名 %q 不合法", fm.Member)
449			}
450			wantFiles[fm.Member] = true
451		}
452	
453		// 实际成员集合必须恰为 {清单, 台账} ∪ 清单所列资料成员：无缺失、无额外。
454		wantMembers := map[string]bool{migrateManifestName: true}
455		if manifest.Ledger != migrateLedgerName {
456			return nil, nil, nil, fmt.Errorf("清单声明的台账成员名为 %q，与约定 %q 不符", manifest.Ledger, migrateLedgerName)
457		}
458		wantMembers[migrateLedgerName] = true
459		for name := range wantFiles {
460			wantMembers[name] = true
461		}
462		if len(members) != len(wantMembers) {
463			return nil, nil, nil, fmt.Errorf("迁移包成员数量不符：应有 %d 个，实际 %d 个（存在缺失或额外成员）",
464				len(wantMembers), len(members))
465		}
466		for name := range wantMembers {
467			if members[name] == nil {
468				return nil, nil, nil, fmt.Errorf("迁移包缺少成员 %s", name)
469			}
470		}
471		for name := range members {
472			if !wantMembers[name] {
473				return nil, nil, nil, fmt.Errorf("迁移包含有清单之外的额外成员 %s", name)
474			}
475		}
476	
477		// 台账内容校验值、格式与整库业务关联。
478		ledgerRaw, err := readZipMember(members[migrateLedgerName])
479		if err != nil {
480			return nil, nil, nil, fmt.Errorf("读取台账成员失败: %w", err)
481		}
482		if int64(len(ledgerRaw)) != manifest.LedgerSize || sha256Hex(ledgerRaw) != manifest.LedgerSHA256 {
483			return nil, nil, nil, fmt.Errorf("台账成员内容损坏：大小或校验值与清单不符")
484		}
485		d, err := decodePackageLedger(ledgerRaw)
486		if err != nil {
487			return nil, nil, nil, err
488		}
489		if err := validateData(d); err != nil {
490			return nil, nil, nil, fmt.Errorf("包内台账业务关联校验失败: %w", err)
491		}
492		// 清单汇总数量须与台账实际成员一致。
493		if manifest.AssetCount != len(d.Assets) {
494			return nil, nil, nil, fmt.Errorf("清单资产数量 %d 与台账实际 %d 不符",
495				manifest.AssetCount, len(d.Assets))
496		}
497		if manifest.AttachmentCount != len(d.Attachments) {
498			return nil, nil, nil, fmt.Errorf("清单附件索引数量 %d 与台账实际 %d 不符",
499				manifest.AttachmentCount, len(d.Attachments))
500		}
501	
502		// 资料映射核对：每条附件索引恰有一个资料成员，每个资料成员恰对应一条
503		// 附件索引；成员内容的大小与 SHA-256 与清单一致（zip 读取本身已校验 CRC）。
504		attachByID := map[string]*Attachment{}
505		for _, a := range d.Attachments {
506			attachByID[a.ID] = a
507		}
508		if len(attachByID) != len(d.Attachments) {
509			return nil, nil, nil, fmt.Errorf("包内台账附件编号重复")
510		}
511		if len(manifest.Files) != len(d.Attachments) {
512			return nil, nil, nil, fmt.Errorf("资料成员数量（%d）与附件索引数量（%d）不符",
513				len(manifest.Files), len(d.Attachments))
514		}
515		attachMember := map[string]string{}
516		contents := map[string][]byte{}
517		for _, fm := range manifest.Files {
518			if attachByID[fm.AttachmentID] == nil {
519				return nil, nil, nil, fmt.Errorf("资料成员 %s 对应的附件编号 %s 在台账中不存在",
520					fm.Member, fm.AttachmentID)
521			}
522			raw, err := readZipMember(members[fm.Member])
523			if err != nil {
524				return nil, nil, nil, fmt.Errorf("读取资料成员 %s 失败: %w", fm.Member, err)
525			}
526			if int64(len(raw)) != fm.Size || sha256Hex(raw) != fm.SHA256 {
527				return nil, nil, nil, fmt.Errorf("资料成员 %s（附件编号 %s）内容损坏：大小或校验值不符",
528					fm.Member, fm.AttachmentID)
529			}
530			attachMember[fm.AttachmentID] = fm.Member
531			contents[fm.Member] = raw
532		}
533		return d, attachMember, contents, nil
534	}
