536	// writeAtomicFile 在 dir 下经临时文件 + rename 原子写入一个普通文件，
537	// 权限 0644；失败由调用方负责清理暂存目录。
538	func writeAtomicFile(path string, data []byte) error {
539		dir := filepath.Dir(path)
540		tmp, err := os.CreateTemp(dir, ".caretrack-restore-*.tmp")
541		if err != nil {
542			return err
543		}
544		tmpName := tmp.Name()
545		if _, err := tmp.Write(data); err != nil {
546			_ = tmp.Close()
547			_ = os.Remove(tmpName)
548			return err
549		}
550		if err := tmp.Sync(); err != nil {
551			_ = tmp.Close()
552			_ = os.Remove(tmpName)
553			return err
554		}
555		if err := tmp.Close(); err != nil {
556			_ = os.Remove(tmpName)
557			return err
558		}
559		if err := os.Chmod(tmpName, 0o644); err != nil {
560			_ = os.Remove(tmpName)
561			return err
562		}
563		if err := os.Rename(tmpName, path); err != nil {
564			_ = os.Remove(tmpName)
565			return err
566		}
567		return nil
568	}
