603		}
604		zr, err := zip.NewReader(pf, fi.Size())
605		if err != nil {
606			_ = pf.Close()
607			return nil, fmt.Errorf("迁移包 %s 不是有效的包格式: %w", absPkg, err)
608		}
609		// 提交前完整核对：格式、版本、业务关联、资料映射、实际成员与校验值。
610		d, attachMember, contents, err := verifyPackage(zr)
611		if err != nil {
