617		}
618	
619		// 附件路径替换映射：副本将位于目标目录内的 attachments/ 子目录，文件名
620		// 沿用包内生成名；这些路径均由工具生成，绝不取自包内原绝对路径，也不会
621		// 按原路径访问外部资料。
622		newPath := map[string]string{}
623		for _, a := range d.Attachments {
