625			np := filepath.Join(absTarget, restoreAttachDir, base)
626			newPath[a.ID] = np
627		}
628		for _, a := range d.Attachments {
629			a.Path = newPath[a.ID]

file.content:
		if err := checkAttachFile(a.Path); err != nil {
